const input = $json.body ?? $json;

const text = (value) =>
  value === null || value === undefined
    ? ''
    : String(value).trim();

const bool = (value) =>
  typeof value === 'boolean'
    ? value
    : ['true', '1', 'yes', 'on'].includes(
        text(value).toLowerCase()
      );

const clinic_name = text(input.clinic_name);
const doctor_name = text(input.doctor_name);
const service_name = text(input.service_name);
const patient_name = text(input.patient_name);
const mobile = text(input.mobile);
const webhook_base_url = text(
  input.webhook_base_url ||
  'http://n8n:5678/webhook'
).replace(/\/+$/, '');
const reset_test_data = bool(input.reset_test_data);
const confirm_seed = bool(input.confirm_seed);

const errors = [];

for (const [field, value] of [
  ['clinic_name', clinic_name],
  ['doctor_name', doctor_name],
  ['service_name', service_name],
  ['patient_name', patient_name],
]) {
  if (!value) {
    errors.push({
      field,
      message: `${field} الزامی است.`,
    });
  }
}

if (!/^\+?[0-9]{8,15}$/.test(mobile)) {
  errors.push({
    field: 'mobile',
    message: 'شماره موبایل تست معتبر نیست.',
  });
}

if (!/^https?:\/\/.+/i.test(webhook_base_url)) {
  errors.push({
    field: 'webhook_base_url',
    message: 'آدرس Webhook معتبر نیست.',
  });
}

if (confirm_seed !== true) {
  errors.push({
    field: 'confirm_seed',
    message: 'ساخت داده تست باید تأیید شود.',
  });
}

return [{
  json: {
    clinic_name,
    doctor_name,
    service_name,
    patient_name,
    mobile,
    webhook_base_url,
    reset_test_data,
    confirm_seed,
    validation_status:
      errors.length === 0 ? 'valid' : 'invalid',
    errors,
  },
}];
